      </text>
      <!-- Missing "e" as dashed outline -->
      <text x="62" y="38" font-family="Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-weight="900" font-size="42" fill="none" stroke="#EB0028" stroke-width="1.5" stroke-dasharray="4,3" letter-spacing="-1">
        e
