      <text x="86" y="38" font-family="Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif" font-weight="900" font-size="42" fill="#EB0028" letter-spacing="-1">
        aForum
      </text>
    </svg>
  </div>

  <!-- Error Message -->
  <div class="error-section">
    <h1>Sorry, we can't find that.</h1>
    <p>Perhaps we can help you find the content you're looking for:</p>
  </div>

  <!-- Search -->
  <form class="search-form" role="search" onsubmit="handleSearch(event)">
    <label for="search-input" class="sr-only" style="position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)">Search IdeaForum</label>
    <input type="text" id="search-input" name="q" placeholder="Search IdeaForum..." autocomplete="off" />
    <button type="submit" aria-label="Search">
      <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2.25">
        <path stroke-linecap="round" stroke-linejoin="round" d="M21 21l-4.35-4.35M11 19a8 8 0 100-16 8 8 0 000 16z"/>
      </svg>
    </button>
  </form>

  <!-- Error Code Bar -->
  <div class="error-code-bar">
    <span>HTTP Error 404</span>
  </div>

  <!-- Divider -->
  <div class="divider" role="separator"></div>

  <!-- Next Steps -->
  <nav class="next-steps" aria-label="Recovery navigation">
    <h2>What's next?</h2>
    <ul>
      <li><a href="/">Go to the homepage</a></li>
      <li><a href="/help">Visit our Help Desk</a></li>
    </ul>
  </nav>

  <!-- Cookie Consent Banner -->
  <div class="cookie-banner" id="cookieBanner" role="region" aria-label="Cookie consent">
    <div class="cookie-banner-text">
      This website utilizes technologies such as cookies to enable essential site functionality, as well as for analytics, personalization, and targeted advertising. To learn more, view the following link: <a href="/privacy" target="_blank" rel="noopener noreferrer">Privacy Policy</a>
    </div>
    <div class="cookie-banner-actions">
      <button class="btn-manage" onclick="openPreferences()" type="button">Manage Preferences</button>
    </div>
  </div>

  <!-- Cookie Preferences Modal -->
  <div class="modal-overlay" id="preferencesModal" role="dialog" aria-modal="true" aria-label="Cookie preferences">
    <div class="modal">
      <div class="modal-header">
        <h3>Cookie Preferences</h3>
        <button class="modal-close" onclick="closePreferences()" aria-label="Close preferences">
          <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2.25">
            <path stroke-linecap="round" stroke-linejoin="round" d="M6 18L18 6M6 6l12 12"/>
          </svg>
        </button>
      </div>
      <div class="modal-body">
        <div class="cookie-category">
          <div class="cookie-category-info">
            <h4>Essential Cookies</h4>
            <p>Required for the site to function properly. These cannot be disabled.</p>
          </div>
          <label class="toggle">
            <input type="checkbox" checked disabled />
            <span class="toggle-slider"></span>
          </label>
        </div>
        <div class="cookie-category">
          <div class="cookie-category-info">
            <h4>Analytics Cookies</h4>
            <p>Help us understand how visitors interact with our site to improve the experience.</p>
          </div>
          <label class="toggle">
            <input type="checkbox" id="analyticsCookies" />
            <span class="toggle-slider"></span>
          </label>
        </div>
        <div class="cookie-category">
          <div class="cookie-category-info">
            <h4>Personalization Cookies</h4>
            <p>Allow us to tailor content and recommendations based on your preferences.</p>
          </div>
          <label class="toggle">
            <input type="checkbox" id="personalizationCookies" />
            <span class="toggle-slider"></span>
          </label>
        </div>
        <div class="cookie-category">
          <div class="cookie-category-info">
            <h4>Advertising Cookies</h4>
            <p>Used to deliver relevant ads and measure the effectiveness of advertising campaigns.</p>
          </div>
          <label class="toggle">
            <input type="checkbox" id="advertisingCookies" />
            <span class="toggle-slider"></span>
          </label>
        </div>
      </div>
      <div class="modal-footer">
        <button class="btn-cancel" onclick="closePreferences()" type="button">Cancel</button>
        <button class="btn-save" onclick="savePreferences()" type="button">Save Preferences</button>
      </div>
    </div>
  </div>

  <script>
    function handleSearch(e) {
      e.preventDefault();
      var query = document.getElementById('search-input').value.trim();
      if (query) {
        window.location.href = '/search?q=' + encodeURIComponent(query);
      }
    }

    function openPreferences() {
      document.getElementById('preferencesModal').classList.add('active');
      document.body.style.overflow = 'hidden';
    }

    function closePreferences() {
      document.getElementById('preferencesModal').classList.remove('active');
      document.body.style.overflow = '';
    }

    function savePreferences() {
      var prefs = {
        essential: true,
        analytics: document.getElementById('analyticsCookies').checked,
        personalization: document.getElementById('personalizationCookies').checked,
        advertising: document.getElementById('advertisingCookies').checked
      };
      try {
        localStorage.setItem('cookiePreferences', JSON.stringify(prefs));
      } catch (e) {}
      closePreferences();
      document.getElementById('cookieBanner').classList.add('hidden');
    }

    // Close modal on overlay click
    document.getElementById('preferencesModal').addEventListener('click', function(e) {
      if (e.target === this) closePreferences();
    });

    // Close modal on Escape key
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') closePreferences();
    });

    // Hide banner if preferences already saved
    (function() {
      try {
        if (localStorage.getItem('cookiePreferences')) {
          document.getElementById('cookieBanner').classList.add('hidden');
        }
      } catch (e) {}
    })();
  </script>

